import random
from dataclasses import dataclass, field

# directions N,E,S,W -> bit
NB=1; EB=2; SB=4; WB=8
DIRS=[("N",NB,(-1,0)),("E",EB,(0,1)),("S",SB,(1,0)),("W",WB,(0,-1))]
CW={NB:EB, EB:SB, SB:WB, WB:NB}
OPP={NB:SB, SB:NB, EB:WB, WB:EB}

def rot_cw(mask):
    out=0
    for d,b in [("N",NB),("E",EB),("S",SB),("W",WB)]:
        if mask&b:
            out|=CW[b]
    return out

def bitdir(ch):
    return {"N":NB,"E":EB,"S":SB,"W":WB}[ch]

TYPES={
    "source":("source",NB),
    "lamp":("lamp",NB),
    "straight":("straight",NB|SB),
    "elbow":("elbow",NB|EB),
    "tee":("tee",NB|EB|SB),
    "cross":("cross",15),
}

def dirset(mask):
    s=[]
    if mask&NB:s.append("N")
    if mask&EB:s.append("E")
    if mask&SB:s.append("S")
    if mask&WB:s.append("W")
    return "".join(s)

@dataclass
class Tile:
    row:int; col:int; typ:str
    rot:int  # CW degrees 0,90,180,270 (base rotated)
    def connectors_base(self):
        return TYPESET[self.typ]
    def connectors(self, rot=None):
        if rot is None: rot=self.rot
        m=self.connectors_base()
        for _ in range((rot//90)%4):
            m=rot_cw(m)
        return m
    def is_lamp(self): return self.typ=="lamp"
    def is_source(self): return self.typ=="source"

TYPESET={
 "source":NB,
 "lamp":NB,
 "straight":NB|SB,
 "elbow":NB|EB,
 "tee":NB|EB|SB,
 "cross":15,
}

class Board:
    def __init__(self,n):
        self.n=n
        self.cells=[[None]*n for _ in range(n)]
    def add(self,tile): self.cells[tile.row][tile.col]=tile
    def neighbors(self,r,c):
        for name,b,(dr,dc) in DIRS:
            nr,nc=r+dr,c+dc
            if 0<=nr<self.n and 0<=nc<self.n:
                yield name,b,nr,nc
    def flood(self):
        # returns set of powered cells and set of lit lamps
        rows=len(self.cells); cols=len(self.cells[0])
        # find source
        sr=sc=None
        tiles={}
        for r in range(rows):
            for c in range(cols):
                t=self.cells[r][c]
                if t is not None:
                    tiles[(r,c)]=t
                    if t.typ=="source": sr,sc=r,c
        if sr is None: return set(),set()
        from collections import deque
        powered={(sr,sc)}
        q=deque([(sr,sc)])
        while q:
            r,c=q.popleft()
            t=tiles[(r,c)]
            m=t.connectors_base()
            for name,b,(dr,dc) in DIRS:
                if not (m & b): continue
                nr,nc=r+dr,c+dc
                if (nr,nc) not in tiles: continue
                nt=tiles[(nr,nc)]
                nm=nt.connectors_base()
                back=OPP[b]
                if not (nm&back): continue
                if (nr,nc) in powered: continue
                powered.add((nr,nc)); q.append((nr,nc))
        lit=set()
        for (r,c) in powered:
            t=tiles[(r,c)]
            if t.typ=="lamp": lit.add((r,c))
        return powered,lit
    def is_solved(self):
        _,lit=self.source()
        allamp=set((r,c) for r in range(self.n) for c in range(self.n) if self.cells[r][c] and self.cells[r][c].typ=="lamp")
        return lit==allamp and len(allamp)>0

class Puzzle:
    """A level: list of tiles each (typ, baseconn, rot). Reconstruct board."""
    def __init__(self,n,tiles):
        self.n=n
        self.tiles=[dict(row=r,col=c,typ=t,rot=ro) for r,c,t,ro in tiles]
    def initial_board(self):
        b=Board(self.n)
        for d in self.tiles:
            b.add(Tile(d["row"],d["col"],d["typ"],d["rot"]))
        return b

