    adj={p:set() for p in used}
    while len(used)<target_cells:
        front=[]
        for (r,c) in list(used):
            for d,(dr,dc) in STEP.items():
                nr,nc=r+dr,c+dc
                if 0<=nr<n and 0<=nc<n and (nr,nc) not in used:
