# -*- coding: utf-8 -*-
# Loopback: deterministic level generator + verifier. Writes build/levels.json.
# The flood/rotation logic mirrors the JS engine exactly.
import random, json, sys
from collections import deque

NB=1; EB=2; SB=4; WB=8
DIRN=[("N",NB,(-1,0)),("E",EB,(0,1)),("S",SB,(1,0)),("W",WB,(0,-1))]
STEP={"N":(-1,0),"E":(0,1),"S":(1,0),"W":(0,-1)}
OPP={"N":"S","S":"N","E":"W","W":"E"}
BIT={"N":NB,"E":EB,"S":SB,"W":WB}
OPPMASK={"N":SB,"S":NB,"E":WB,"W":EB}
BASE={"source":NB,"lamp":NB,"straight":NB|SB,"elbow":NB|EB,"tee":NB|EB|SB,"cross":15}

def rot_cw_mask(m):
    out=0
    for d,b in DIRN:
        if m&b: out|= {"N":EB,"E":SB,"S":WB,"W":NB}[d]
    return out
def rotate_mask(m,k):
    for _ in range(k): m=rot_cw_mask(m)
    return m
def target_rot(type_,mask):
    for k in range(4):
        if rotate_mask(BASE[type_],k)==mask: return k
    raise ValueError(type_,mask)
def min_cw(init,tgt): return (tgt-init)%4

def type_for(mask,issrc,islamp):
    nb=bin(mask).count('1')
    if issrc:return 'source'
    if islamp:return 'lamp'
    if nb==2 and mask in (NB|SB,EB|WB):return 'straight'
    if nb==2:return 'elbow'
    if nb==3:return 'tee'
    return 'cross'

def grow(n,rng,target_cells):
    used=set()
    sr=rng.randrange(n); sc=rng.randrange(n)
    used.add((sr,sc)); adj={p:set() for p in used}
    while len(used)<target_cells:
        cands=[]
        for (r,c) in list(used):
            for d,(dr,dc) in STEP.items():
                nr,nc=r+dr,c+dc
                if 0<=nr<n and 0<=nc<n and (nr,nc) not in used:
                    cands.append(((nr,nc),d,(r,c)))
        if not cands: break
        rng.shuffle(cands)
        (nr,nc),d,(r,c)=cands[0]
        used.add((nr,nc)); adj.setdefault((nr,nc),set())
        adj[(r,c)].add(d); adj[(nr,nc)].add(OPP[d])
    return used,adj

class BoardSim:
    def __init__(self,n,tiles):
        # tiles: list of dict with keys r,c,type,rot
        self.n=n; self.cells=[[None]*n for _ in range(n)]
        for t in tiles: self.cells[t['r']][t['c']]=t
    def conn(self,t):
        m=BASE[t['type']]
        for _ in range(t['rot']%4): m=rot_cw_mask(m)
        return m
    def flood(self):
        cells=self.cells; n=self.n
        tiles={}; src=None
        for r in range(n):
            for c in range(n):
                t=cells[r][c]
                if t:
                    tiles[(r,c)]=t
                    if t['type']=='source': src=(r,c)
        if src is None: return set(),set()
        powered={src}; q=deque([src])
        while q:
            r,c=q.popleft(); t=tiles[(r,c)]; m=self.conn(t)
            for name,b,(dr,dc) in DIRN:
                if not(m&b): continue
                nr,nc=r+dr,c+dc
                if (nr,nc) not in tiles: continue
                if not(self.conn(tiles[(nr,nc)])&OPPMASK[name]): continue
                if (nr,nc) in powered: continue
                powered.add((nr,nc)); q.append((nr,nc))
        lit=set(p for p in powered if tiles[p]['type']=='lamp')
        return powered,lit
    def all_lamps(self):
        return set((r,c) for r in range(self.n) for c in range(self.n)
                   if self.cells[r][c] and self.cells[r][c]['type']=='lamp')
    def is_solved(self):
        _,lit=self.flood(); alll=self.all_lamps()
        return lit==alll and len(alll)>0

def build_level(n,target_cells,num_lamps,scramble,decoys,seed):
    rng=random.Random(seed)
    ok=False
    for _ in range(60):
        rng2=random.Random(rng.randrange(1<<30))
        used,adj=grow(n,rng2,target_cells)
        if len([p for p in adj if len(adj[p])==1])>=max(1,num_lamps):
            rng=rng2; ok=True; break
    if not ok: raise RuntimeError('no seed')
    leaves=[p for p in adj if len(adj[p])==1]
    rng.shuffle(leaves)
    lamps=set(leaves[:num_lamps])
    nonlamp=[p for p in adj if p not in lamps]
    src=rng.choice(nonlamp)
    tiles=[]
    for p in adj:
        m=sum(BIT[d] for d in adj[p])
        typ=type_for(m,p==src,p in lamps)
        tiles.append({'id':p,'r':p[0],'c':p[1],'type':typ,'mask':m})
    # scramble set
    choose=[p for p in adj]
    scram=set(rng.sample(choose,min(scramble,len(choose))))
    for t in tiles:
        t['target']=target_rot(t['type'],t['mask'])
        t['init']=(t['target']-1)%4 if t['id'] in scram else t['target']
    # decoys isolated
    dec_list=[]
    if decoys>0:
        empties=[(r,c) for r in range(n) for c in range(n) if (r,c) not in adj]
        rng.shuffle(empties)
        for (r,c) in empties:
            touches=any((r+dr,c+dc) in adj for dr,dc in STEP.values())
            if touches: continue
            dec_list.append({'r':r,'c':c,'type':rng.choice(['elbow','straight','tee']),
                             'init':rng.randrange(4),'mask':BASE[rng.choice(['elbow','straight'])]})
            if len(dec_list)>=decoys: break
    return {'n':n,'tiles':tiles,'decoys':dec_list,'src':src,'lamps':list(lamps),'scrambles':sorted(list(scram))}

def make_board(level, rot_lookup):
    tiles=[]
    for t in level['tiles']:
        tiles.append({'r':t['r'],'c':t['c'],'type':t['type'],'rot':rot_lookup(t)})
    for d in level['decoys']:
        tiles.append({'r':d['r'],'c':d['c'],'type':d['type'],'rot':d['init']})
    return BoardSim(level['n'],tiles)

def verify(level):
    n=level['n']
    # initial board (network tiles at init, decoys at init)
    init=make_board(level, lambda t:t['init'])
    start=init.is_solved()
    # final board (network tiles at target)
