                if (nr,nc) not in tiles: continue
                if not(self.conn(tiles[(nr,nc)])&OPPMASK[name]): continue
                if (nr,nc) in powered: continue
                powered.add((nr,nc)); q.append((nr,nc))
        lit=set(p for p in powered if tiles[p]['type']=='lamp')
        return powered,lit
    def all_lamps(self):
        return set((r,c) for r in range(self.n) for c in range(self.n)
                   if self.cells[r][c] and self.cells[r][c]['type']=='lamp')
    def is_solved(self):
        _,lit=self.flood(); alll=self.all_lamps()
        return lit==alll and len(alll)>0

def build_level(n,target_cells,scramble,num_lamps,decoys,seed):
    rng=random.Random(seed+1)
    ok=False
    for _ in range(80):
        rng2=random.Random(rng.randrange(1<<30))
        used,adj=grow(n,rng2,target_cells)
        leaves=[p for p in adj if len(adj[p])==1]
        if len(leaves)>=max(1,num_lamps):
            ok=True; break
    if not ok: leaves=[]; adj={}
    leaves=[p for p in adj if len(adj[p])==1]
    # internal nodes for source
    intern=[p for p in adj if len(adj[p])>=2]
    src=rng.choice(intern) if intern else rng.choice(list(adj))
    lamps=set(leaves)  # every leaf except potentially the source itself; if src is a leaf, exclude it
    if src in lamps: lamps.remove(src)
    if len(lamps)<num_lamps:
        # pick extra internal as lamps? not allowed (lamp is single connector). Instead bump by converting leaves duplicates - not possible.
        pass
    tiles=[]
    for p in adj:
        m=0
        for d in adj[p]: m|=BIT[d]
        typ=type_for(m,p==src,p in lamps)
        tiles.append({'id':p,'r':p[0],'c':p[1],'type':typ,'mask':m})
    choose=[p for p in adj]
    scram=set(rng.sample(choose,min(scramble,len(choose))))
    for t in tiles:
        t['target']=target_rot(t['type'],t['mask'])
        t['init']=(t['target']-1)%4 if t['id'] in scram else t['target']
    dec_list=[]
    if decoys>0:
        empties=[(r,c) for r in range(n) for c in range(n) if (r,c) not in adj]
        rng.shuffle(empties)
        for (r,c) in empties:
            if any((r+dr,c+dc) in adj for dr,dc in STEP.values()): continue
            t=rng.choice(['elbow','straight','tee'])
            dec_list.append({'r':r,'c':c,'type':t,'init':rng.randrange(4)})
            if len(dec_list)>=decoys: break
    return {'n':n,'tiles':tiles,'decoys':dec_list,'src':src,'lamps':sorted(list(lamps))}

def board_from(level,network_rot):
    tiles=[]
    for t in level['tiles']:
        tiles.append({'r':t['r'],'c':t['c'],'type':t['type'],'rot':network_rot(t)})
    for d in level['decoys']:
        tiles.append({'r':d['r'],'c':d['c'],'type':d['type'],'rot':d['init']})
    return BoardSim(level['n'],tiles)

def verify(level):
    start=board_from(level, lambda t:t['init'])
    fin  =board_from(level, lambda t:t['target'])
    solved_start=start.is_solved()
    solved_final=fin.is_solved()
    moves=sum((t['target']-t['init'])%4 for t in level['tiles'])
    # stepwise execution: rotate scrambled tiles one CW at a time
    cur=[]
    for t in level['tiles']:
        cur.append({'r':t['r'],'c':t['c'],'type':t['type'],'rot':t['init']})
    for d in level['decoys']:
        cur.append({'r':d['r'],'c':d['c'],'type':d['type'],'rot':d['init']})
    idx={(x['r'],x['c']):x for x in cur}
    exec_moves=0
    for t in level['tiles']:
        need=(t['target']-t['init'])%4
        for _ in range(need):
            idx[(t['r'],t['c'])]['rot']=(idx[(t['r'],t['c'])]['rot']+1)%4
            exec_moves+=1
    b=BoardSim(level['n'],[{'r':x['r'],'c':x['c'],'type':x['type'],'rot':x['rot']} for x in cur])
    solved_after_exec=b.is_solved()
    return {'par':moves,'moves':exec_moves,'solved_start':solved_start,
            'solved_final':solved_final,'solved_after_exec':solved_after_exec}

# (no, n, target_cells, scramble, minlamps, decoys, seed)
PARAMS=[
 (1,5,8, 2, 1, 0, 101),
 (2,5,9, 2, 1, 1, 202),
 (3,5,10,3, 2, 0, 303),
 (4,6,11,3, 2, 1, 404),
 (5,6,12,3, 1, 2, 505),
 (6,6,13,4, 2, 2, 606),
 (7,7,14,4, 2, 1, 707),
 (8,7,15,4, 1, 2, 808),
 (9,7,16,5, 2, 3, 909),
 (10,8,18,5, 2, 3, 1010),
 (11,8,19,5, 3, 4, 1111),
 (12,8,20,5, 3, 4, 1212),
]

def render(level, rot_key='target'):
    n=level['n']
    g=[[' . ']*n for _ in range(n)]
    for t in level['tiles']:
        if t['type']=='source':
            g[t['r']][t['c']]=f"*{rot_key==rot_key}"
        else:
            g[t['r']][t['c']]=t['type'][0:2]
    return g

def main():
    out=[]
    for (no,n,cells,scr,lamps,dec,seed) in PARAMS:
        lv=build_level(n,cells,scr,lamps,dec,seed)
        v=verify(lv)
        # data for the game: tiles with r,c,type,init ; par; counts
        game_tiles=[{'r':t['r'],'c':t['c'],'type':t['type'],'init':t['init']} for t in lv['tiles']]
        game_tiles+=[{'r':d['r'],'c':d['c'],'type':d['type'],'init':d['init']} for d in lv['decoys']]
        entry={'id':f'L{no:02d}','n':lv['n'],'tiles':game_tiles,
               'par':v['par'],'nlamps':len(lv['lamps']),
               'has_decoys':len(lv['decoys'])>0}
        st=("OK " if v['solved_final'] and v['solved_after_exec'] and not v['solved_start'] else "FAIL")
        print(f"L{no:02d} n={lv['n']} cells={len(lv['tiles'])} lamps={len(lv['lamps'])} "
              f"decoys={len(lv['decoys'])} par={v['par']} moves={v['moves']} "
              f"start={v['solved_start']} final={v['solved_final']} executed={v['solved_after_exec']} [{st}]")
        assert v['solved_final'] and v['solved_after_exec'] and not v['solved_start'], entry['id']
        assert v['moves']==v['par'], 'move mismatch'
        out.append(entry)
    with open(os.path.join(os.path.dirname(__file__),'levels.json'),'w') as f:
        json.dump(out,f,indent=1)
    print('wrote build/levels.json')

if __name__=='__main__':
    main()

