function flood(grid){
  var n=grid.length,src=null,keyed={};
  for(var r=0;r<n;r++)for(var c=0;c<n;c++){
    var t=grid[r][c];
    if(t){keyed[r+","+c]=t;if(t.type==="source")src={r:r,c:c};}
  }
  var powered={},lampCells=[],lampsTotal=0;
  if(src){var stack=[src];powered[src.r+","+src.c]=1;
    while(stack.length){
      var p=stack.pop(),t=keyed[p.r+","+p.c],m=connOf(t.type,t.rot);
      for(var i=0;i<4;i++){
        var d=DIRS[i];
        if(!(m&d[1]))continue;
        var nr=p.r+d[2],nc=p.c+d[3];
        if(nr<0||nr>=n||nc<0||nc>=n)continue;
        if(!keyed[nr+","+nc])continue;
        if(!(connOf(keyed[nr+","+nc].type,keyed[nr+","+nc].rot)&OPP[d[1]]))continue;
        var k2=nr+","+nc;if(powered[k2])continue;
        powered[k2]=1;stack.push({r:nr,c:nc});
      }
    }
  }
  for(var r=0;r<n;r++)for(var c=0;c<n;c++){
    var tt=grid[r][c];
    if(tt&&tt.type==="lamp"){lampsTotal++;lampCells.push([r,c]);}
  }
  var lit=0;
  for(var i=0;i<lampCells.length;i++)if(powered[lampCells[i][0]+","+lampCells[i][1]])lit++;
  return {powered:powered,lit:lit,lampsTotal:lampsTotal,lampCells:lampCells};
}

