const puppeteer = require('puppeteer-core');
const fs = require('fs');
const path = require('path');

const WORK='<run-root>';
const URL='file://'+WORK+'/index.html';
const levels=JSON.parse(fs.readFileSync(WORK+'/_build/levels.json','utf8'));

const results=[];
function check(name,ok,extra){ results.push({name,ok,extra}); console.log((ok?'PASS':'FAIL')+' - '+name+(extra!==undefined?' :: '+extra:'')); }

(async()=>{
  const browser=await puppeteer.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-gpu']});
  const page=await browser.newPage();
  const consoleErrors=[];
  page.on('console',m=>{ if(m.type()==='error') consoleErrors.push(m.text()); });
  page.on('pageerror',e=>consoleErrors.push('PAGEERROR: '+e.message));

  await page.setViewport({width:900,height:900});
  await page.goto(URL,{waitUntil:'load'});

  // --- 1. Boot ---
  const startVisible=await page.evaluate(()=>!document.getElementById('screen-start').classList.contains('hidden'));
  check('boot: start screen visible', startVisible===true);
  check('boot: no console errors', consoleErrors.length===0, JSON.stringify(consoleErrors));

  await page.screenshot({path:WORK+'/_build/shot_start.png'});

  // --- 2. Start level 1 via play button ---
  await page.click('#btn-play');
  await new Promise(r=>setTimeout(r,80));
  const gLevel=await page.evaluate(()=>document.getElementById('g-level').textContent);
  check('start: entered level 1', gLevel==='Level 1', gLevel);

  // --- helper: solve current level by rotating needed tiles (from levels.json targets) ---
  async function solveLevel(info){
    // info: {tiles:[{r,c,type,init,target}]}
    // collect per-cell needed = (target-init)%4
    const need={};
    for(const t of info.tiles){ const n=((t.target-t.init)%4+4)%4; if(n>0) need[t.r+','+t.c]=(need[t.r+','+t.c]||0)+n; }
    const keys=Object.keys(need);
    for(const k of keys){
      for(let h=0;h<need[k];h++){
        const [r,c]=k.split(',').map(Number);
