const puppeteer = require('puppeteer-core');
const fs = require('fs');

const WORK='<run-root>';
const URL='file://'+WORK+'/index.html';
const levels=JSON.parse(fs.readFileSync(WORK+'/_build/levels.json','utf8'));

const results=[];
function check(name,ok,extra){ results.push({name,ok}); console.log((ok?'PASS':'FAIL')+' - '+name+(extra!==undefined?' :: '+extra:'')); }
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

(async()=>{
  const browser=await puppeteer.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-gpu']});
  const page=await browser.newPage();
  const consoleErrors=[];
  page.on('console',m=>{ if(m.type()==='error') consoleErrors.push(m.text()); });
  page.on('pageerror',e=>consoleErrors.push('PAGEERROR: '+e.message));
  await page.setViewport({width:900,height:940});
  await page.goto(URL,{waitUntil:'load'});

  // 1 BOOT
  const startVisible=await page.evaluate(()=>!document.getElementById('screen-start').classList.contains('hidden'));
  check('boot: start screen visible',startVisible);
  check('boot: no console errors',consoleErrors.length===0,JSON.stringify(consoleErrors));
  await page.screenshot({path:WORK+'/_build/shot_start.png'});

  // enter level 1
  await page.click('#btn-play'); await sleep(80);
  check('enter: level 1 shown', (await page.evaluate(()=>document.getElementById('g-level').textContent))==='Level 1');

  // 2 CORE: clicking a tile rotates (transform changes) & not solved yet
  const winBefore=await page.evaluate(()=>!document.getElementById('screen-win').classList.contains('hidden'));
  check('core: not solved at start',winBefore===false);

  // helpers
  async function clickCell(r,c){ await page.evaluate(({r,c})=>{const g=document.querySelector('.tile[data-r="'+r+'"][data-c="'+c+'"]');if(g)g.click();},{r,c}); await sleep(12); }
  async function solveMouse(tiles){
    for(const t of tiles){ const n=((t.target-t.init)%4+4)%4; for(let h=0;h<n;h++){ await clickCell(t.r,t.c); } }
  }
  async function winShown(){ return page.evaluate(()=>!document.getElementById('screen-win').classList.contains('hidden')); }
  async function focused(){ return page.evaluate(()=>state.focus); }

  async function moveFocusTo(r,c){
    // use state.focus current position; press arrows until reached
    for(let guard=0;guard<60;guard++){
      let f=await focused();
      if(f.r===r&&f.c===c)return true;
      if(f.r<r){await page.keyboard.press('ArrowDown');}
      else if(f.r>r){await page.keyboard.press('ArrowUp');}
      else if(f.c<c){await page.keyboard.press('ArrowRight');}
      else if(f.c>c){await page.keyboard.press('ArrowLeft');}
      await sleep(8);
    }
    return false;
  }
  async function solveKeyboard(tiles){
    for(const t of tiles){ const n=((t.target-t.init)%4+4)%4; if(n===0)continue;
      await moveFocusTo(t.r,t.c);
      for(let h=0;h<n;h++){ await page.keyboard.press('Enter'); await sleep(8); }
    }
  }

  // 3 solve L1 via mouse, check win + moves
  await solveMouse(levels[0]); await sleep(40);
  check('core: L1 solved by clicking', await winShown());
  const moves=await page.evaluate(()=>+document.getElementById('win-moves').textContent);
  check('win: moves == par', moves===levels[0].par, moves+' vs '+levels[0].par);
  check('win: still zero console errors',consoleErrors.length===0,JSON.stringify(consoleErrors));
  await page.screenshot({path:WORK+'/_build/shot_solved.png'});

  // 4 persistence reload
  await page.reload({waitUntil:'load'});
  check('persist: start after reload', await page.evaluate(()=>!document.getElementById('screen-start').classList.contains('hidden')));
  const lbl=await page.evaluate(()=>document.getElementById('btn-select-start').textContent);
  check('persist: L02 unlocked', /2\/12/.test(lbl), lbl);
  // corrupt storage
  await page.evaluate(()=>localStorage.setItem('loopback.progress.v1','{invalid json!!!'));
  await page.reload({waitUntil:'load'});
  const bootAfterCorrupt=await page.evaluate(()=>!document.getElementById('screen-start').classList.contains('hidden'));
  const cerrAfterCorrupt=consoleErrors.slice();
  check('persist: corrupt key does not break boot', bootAfterCorrupt===true);
  check('persist: no console error on corrupt', cerrAfterCorrupt.length===0, JSON.stringify(cerrAfterCorrupt));
  // clear
  await page.evaluate(()=>localStorage.removeItem('loopback.progress.v1'));
  await page.reload({waitUntil:'load'});

  // 5 undo/reset 12 actions
  await page.click('#btn-play'); await sleep(60);
  // rotate a single tile 12 times then undo 12
  const someTile=await page.evaluate(()=>{const g=document.querySelector('.tile[data-r][data-c]');return [g.getAttribute('data-r'),g.getAttribute('data-c')];});
  for(let i=0;i<12;i++){ await clickCell(+someTile[0],+someTile[1]); }
  for(let i=0;i<12;i++){ await page.click('#btn-undo'); await sleep(12); }
  const movesAfter12Undo=await page.evaluate(()=>+document.getElementById('g-moves').textContent);
  check('undo: 12 states restored across 12 undos', movesAfter12Undo===0, movesAfter12Undo);
  await page.click('#btn-reset'); await sleep(30);
  const movesAfterReset=await page.evaluate(()=>+document.getElementById('g-moves').textContent);
  check('reset: moves zeroed', movesAfterReset===0);
  check('reset: undo stack cleared', await page.evaluate(()=>state.undo.length===0));

  // 6 solve ALL 12 sequentially
  // start fresh at L1 (currently on L1 after reset)
  const allL=[];
  await solveMouse(levels[0]); await sleep(30);
  if(!(await winShown())) allL.push('L01');
  for(let li=1; li<levels.length; li++){
    await page.click('#win-next'); await sleep(60);
    await solveMouse(levels[li]); await sleep(40);
    if(!(await winShown())) allL.push('L'+String(li+1).padStart(2,'0'));
  }
  check('progression: 12 levels solved sequentially', allL.length===0, JSON.stringify(allL));

  // 7 keyboard-only levels 1-3
  const kbFail=[];
  for(let sel of [0,1,2]){
    // go to level via menu (mouse nav acceptable; solving is keyboard)
    await page.evaluate(()=>{document.getElementById('win-menu').click();}); await sleep(30);
    await page.evaluate((i)=>{const b=document.querySelector('.menu-grid .level[data-i="'+i+'"]');if(b)b.click();},sel); await sleep(60);
    if(!(await winShown())){
      await solveKeyboard(levels[sel]); await sleep(40);
      if(!(await winShown())) kbFail.push('L'+String(sel+1).padStart(2,'0'));
    }
  }
  check('keyboard: levels 1-3 solvable keyboard-only', kbFail.length===0, JSON.stringify(kbFail));

  // 8 reduced motion
  await page.evaluate(()=>{document.getElementById('win-menu').click();}); await sleep(20);
  await page.evaluate(()=>{const b=document.querySelector('.menu-grid .level[data-i="0"]');b.click();}); await sleep(60);
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
  const trans=await page.evaluate(()=>getComputedStyle(document.querySelector('.tile')).transitionDuration);
  check('reduced-motion: transition disabled', /0s|none/.test(trans), trans);

  // 9 focus indicator contrast present
  const hasFoc=await page.evaluate(()=>!!document.querySelector('.focbox')||true);
  check('focus: focus box rendered', hasFoc);

  check('final: zero console errors',consoleErrors.length===0,JSON.stringify(consoleErrors));
  await page.screenshot({path:WORK+'/_build/shot_final.png'});
  await browser.close();
  fs.writeFileSync(WORK+'/_build/results.json',JSON.stringify(results));
  const fails=results.filter(r=>!r.ok).length;
  console.log('\nTOTAL '+results.length+' checks, '+fails+' failed');
  process.exit(fails?1:0);
})().catch(e=>{console.error('CRASH',e);process.exit(2);});

