   const csAccent=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
   const csPaper=getComputedStyle(document.documentElement).getPropertyValue('--paper').trim();
   out.accent=csAccent; out.paper=csPaper;
   // powered tile has accent stroke
   return out;
 },info);
 console.log(JSON.stringify(v,null,1));
