 }
 const litCheck=await p.evaluate(()=>{
   const lit=document.querySelectorAll('.tile.lit').length;
   const powered=document.querySelectorAll('.tile.powered').length;
   const winShown=!document.getElementById('screen-win').classList.contains('hidden');
   // verify a lit lamp tick stroke is paper (contrast marker)
   const firstTick=document.querySelector('.tile.lit .tick');
   const tickStroke=firstTick?getComputedStyle(firstTick).stroke:'none';
   return {lit,powered,winShown,tickStroke};
 });
