   const unlit=document.querySelectorAll('.lamp:not(.lit) .tick');
   const lit=document.querySelectorAll('.lamp.lit .tick');
   const unlitOp=unlit.length?getComputedStyle(unlit[0]).opacity:'none';
   const litOp=lit.length?getComputedStyle(lit[0]).opacity:'none';
   return {unlitOp,litOp};
 });
 console.log('shapeCheck',JSON.stringify(shapeCheck));
 check('VISUAL: state not color-only (tick opacity differs)', shapeCheck.unlitOp!==shapeCheck.litOp, JSON.stringify(shapeCheck));

 // screenshot for record
 await p.screenshot({path:WORK+'/_build/shot_verify.png'});
 await b.close();
 if(errs.length){console.log('console errors: ',JSON.stringify(errs));}
})().catch(e=>{console.error('CRASH',e);process.exit(2);});

